"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Command, CommandEmpty, CommandHint, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { Field, useFieldControl, useLineOrigin } from "@/components/ui/field"
import { Popover, PopoverAnchor, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

type ComboboxOption = { value: string; label: string; hint?: string }

type ComboboxOptions = {
  /** Labels should be unique: they are what the list is matched and marked on. */
  options: ComboboxOption[]
  /** Set above the line. Left out, label it with a Field, or with aria-label. */
  label?: string
  /** What the closed line says before anything is chosen. */
  placeholder?: string
  /** Shown when nothing matches. Name something to try. */
  empty?: string
  /** Pins a state for documentation ("hover", "focus"); set on the trigger. */
  "data-force"?: string
}

type ComboboxBase = Omit<React.ComponentProps<"button">, "value" | "defaultValue" | "onChange" | "type"> & ComboboxOptions

type ComboboxOne = ComboboxBase & {
  multiple?: false
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /**
   * list (default): a line that opens a list; what you type is marked in each match.
   * concordance: the matches hang from what you typed, lined up on it, as a concordance sets a word.
   * pencil: you type on the line itself, and the rest of the best match is pencilled in after the caret.
   */
  variant?: "list" | "concordance"
}

type ComboboxPencilProps = Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "type"> & ComboboxOptions & {
  multiple?: false
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  variant: "pencil"
}

type ComboboxMany = ComboboxBase & {
  /**
   * Any number of choices. They are written on the line as one sentence in your italic ("Didot, Futura and Univers"),
   * each struck and taken out by pressing it; the list stays open while you choose, and a chosen row turns italic.
   */
  multiple: true
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  /** With `name`, each chosen value is sent with the form as its own entry. */
  name?: string
  variant?: "list" | "concordance"
}

type ComboboxProps = ComboboxOne | ComboboxMany | ComboboxPencilProps

/** A tempo token in milliseconds: the tokens are written in seconds or milliseconds. */
const ms = (v: string, fallback: number) => (v.trim().endsWith("ms") ? parseFloat(v) : parseFloat(v) * 1000) || fallback
const still = () => typeof matchMedia === "undefined" || matchMedia("(prefers-reduced-motion: reduce)").matches

/**
 * A field that suggests. Open it, type, and the letters you typed are marked in each match.
 * The chosen label is yours, so it sits on the line in italic. Enter, Space or the down arrow
 * opens the list; Enter picks; Escape closes it and puts focus back on the line.
 */
function Combobox(props: ComboboxProps) {
  const inField = Boolean(useFieldControl().id)
  const { label, id } = props
  // On its own, a label brings its own Field so the line, the label and the hint wire up the same way.
  const own = Boolean(label && !inField)
  const control = { ...props, id: own ? undefined : id }
  const node = control.variant === "pencil" ? <ComboboxPencil {...control} /> : <ComboboxControl {...control} />
  return own ? (
    <Field label={label} id={id} className="ot-combo-field">
      {node}
    </Field>
  ) : (
    node
  )
}

/** Where the query first sits in a label: the words before it, the match, and the words after. */
function split(label: string, query: string) {
  const q = query.trim()
  const i = q ? label.toLowerCase().indexOf(q.toLowerCase()) : -1
  return i < 0 ? ["", "", label] : [label.slice(0, i), label.slice(i, i + q.length), label.slice(i + q.length)]
}

function ComboboxControl({
  options,
  value: valueProp,
  defaultValue,
  onValueChange,
  multiple,
  variant,
  label,
  placeholder = multiple ? "Choose any" : "Choose one",
  empty = "Nothing matches. Try part of a name.",
  className,
  id,
  onKeyDown,
  name,
  ...props
}: ComboboxOne | ComboboxMany) {
  const field = useFieldControl()
  const [open, setOpen] = React.useState(false)
  const listId = React.useId()
  const [own, setOwn] = React.useState<string | string[] | undefined>(defaultValue)
  const value = valueProp ?? own
  // Single or many, the choices are one list here: what's chosen, in the order it was chosen.
  const picked = multiple ? ((value as string[] | undefined) ?? []) : value ? [value as string] : []
  const chosen = multiple ? undefined : options.find((o) => o.value === value)
  const concordance = variant === "concordance"
  const [query, setQuery] = React.useState("")
  const list = React.useRef<HTMLDivElement>(null)
  const was = React.useRef<Map<string, number> | null>(null)

  const set = (next: string | string[]) => {
    if (valueProp === undefined) setOwn(next)
    ;(onValueChange as ((v: string | string[]) => void) | undefined)?.(next)
  }
  const pick = (next: string) => {
    if (!multiple) {
      set(next)
      return setOpen(false)
    }
    // Many: the row toggles and the list stays open for the next.
    set(picked.includes(next) ? picked.filter((v) => v !== next) : [...picked, next])
  }

  // The concordance's glide: each row's words were somewhere before the query changed; they slide to the new axis.
  const starts = () => new Map(Array.from(list.current?.querySelectorAll<HTMLElement>("[cmdk-item]") ?? [], (row) => [row.dataset.value ?? "", row.querySelector(".ot-combo-pre > span")?.getBoundingClientRect().left ?? 0]))
  React.useLayoutEffect(() => {
    const before = was.current
    was.current = null
    if (!before || !list.current || still()) return
    const css = getComputedStyle(list.current)
    const now = starts()
    list.current.querySelectorAll<HTMLElement>("[cmdk-item]").forEach((row) => {
      const from = before.get(row.dataset.value ?? "")
      const to = now.get(row.dataset.value ?? "")
      if (from === undefined || to === undefined || Math.abs(from - to) < 0.5) return
      row.animate([{ translate: `${from - to}px 0` }, { translate: "0 0" }], { duration: ms(css.getPropertyValue("--ot-moderato"), 320), easing: css.getPropertyValue("--ot-breath").trim() || "ease" })
    })
  }, [query])

  const button = (
    <PopoverTrigger asChild>
      <button
        type="button"
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        data-slot="combobox"
        data-placeholder={picked.length ? undefined : ""}
        className={cn("ot-combo", !multiple && className)}
        name={multiple ? undefined : name}
        {...props}
        id={id ?? field.id}
        aria-label={props["aria-label"]}
        aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
        aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
        onKeyDown={(e) => {
          onKeyDown?.(e)
          if (e.key === "ArrowDown" && !e.defaultPrevented) {
            e.preventDefault()
            setOpen(true)
          }
        }}
      >
        <span data-slot="combobox-value" className="ot-combo-value">
          {multiple ? picked.length ? <span className="ot-sr">{picked.length} chosen</span> : placeholder : (chosen?.label ?? placeholder)}
        </span>
      </button>
    </PopoverTrigger>
  )

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        if (!next) setQuery("")
      }}
    >
      {multiple ? (
        // The line holds the sentence of what you chose, then the rest of the line opens the list. The words are
        // series tags, siblings of the trigger, so taking out the last one hands focus on to it.
        <PopoverAnchor asChild>
          <div data-slot="combobox-line" className={cn("ot-combo-many", className)} data-disabled={props.disabled || undefined}>
            {picked.map((v) => (
              <Badge
                key={v}
                variant="series"
                onRemove={props.disabled ? undefined : () => set(picked.filter((x) => x !== v))}
              >
                {options.find((o) => o.value === v)?.label ?? v}
              </Badge>
            ))}
            {button}
            {name ? picked.map((v) => <input key={v} type="hidden" name={name} value={v} disabled={props.disabled} />) : null}
          </div>
        </PopoverAnchor>
      ) : (
        button
      )}
      <PopoverContent
        data-slot="combobox-content"
        data-variant={concordance ? "concordance" : undefined}
        data-multiple={multiple ? "" : undefined}
        className="ot-combo-pop"
        aria-label={label ?? placeholder}
      >
        <Command id={listId} loop label={label ?? placeholder} defaultValue={chosen?.label}>
          <CommandInput
            placeholder="Type to narrow the list"
            onValueChange={(next) => {
              if (concordance) was.current = starts()
              setQuery(next)
            }}
          />
          <CommandList ref={list} data-slot="combobox-list" aria-multiselectable={multiple || undefined}>
            <CommandEmpty>{empty}</CommandEmpty>
            {options.map((o) => {
              const [pre, hit, post] = split(o.label, query)
              const on = picked.includes(o.value)
              return (
                <CommandItem key={o.value} value={o.label} keywords={o.hint ? [o.hint] : undefined} data-chosen={on ? "" : undefined} aria-checked={multiple ? on : undefined} onSelect={() => pick(o.value)}>
                  {concordance ? (
                    <>
                      <span className="ot-combo-pre">
                        <span>{pre}</span>
                      </span>
                      <span className="ot-combo-hit">{hit ? <mark>{hit}</mark> : null}</span>
                      <span className="ot-combo-post">
                        {post}
                        {o.hint ? <CommandHint>{o.hint}</CommandHint> : null}
                      </span>
                    </>
                  ) : (
                    o.label
                  )}
                  {!concordance && o.hint ? <CommandHint>{o.hint}</CommandHint> : null}
                </CommandItem>
              )
            })}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/** The highlighter over what you typed, as the list's rows mark it. */
function Marked({ text, query }: { text: string; query: string }) {
  const [pre, hit, post] = split(text, query)
  return (
    <span className="ot-combo-name">
      {pre}
      {hit ? <mark>{hit}</mark> : null}
      {post}
    </span>
  )
}

const SHOWN = 5 // ponytail: the pencil lists the first five matches, so it never scrolls; typing narrows the rest.

/**
 * The pencil: an input on the line itself. The best match's remaining letters are pencilled in after the caret,
 * in our roman; Tab or the right arrow (at the end) takes them and they ink into your italic. Up and Down move
 * through the few matches below the line, Enter picks one, Escape puts the line back.
 */
function ComboboxPencil({ options, value: valueProp, defaultValue, onValueChange, label, placeholder = "Start typing", empty = "Nothing matches. Try part of a name.", className, id, disabled, readOnly, dir = "auto", "aria-label": named, "data-force": force, ref, onFocus, onPointerDown, onChange, onClick, onKeyDown, onBlur, variant, multiple, ...props }: ComboboxPencilProps) {
  void variant
  void multiple
  const field = useFieldControl()
  const listId = React.useId()
  const input = React.useRef<HTMLInputElement>(null)
  const composedRef = useComposedRefs(input, ref)
  const [own, setOwn] = React.useState(defaultValue)
  const value = valueProp ?? own
  const chosen = options.find((o) => o.value === value)
  const [text, setText] = React.useState(chosen?.label ?? "")
  const [open, setOpen] = React.useState(false)
  const [at, setAt] = React.useState(0)
  // A controlled value that changes from outside rewrites the line (unless you're typing on it).
  const [seen, setSeen] = React.useState(chosen?.label)
  if (seen !== chosen?.label) {
    setSeen(chosen?.label)
    if (!open) setText(chosen?.label ?? "")
  }

  const q = text.trim().toLowerCase()
  const found = q ? options.filter((o) => o.label.toLowerCase().includes(q) || o.hint?.toLowerCase().includes(q)) : options
  // Rows that begin with what you typed come first: they are the ones the pencil can finish.
  const shown = [...found.filter((o) => o.label.toLowerCase().startsWith(q)), ...found.filter((o) => !o.label.toLowerCase().startsWith(q))].slice(0, SHOWN)
  const active = open ? shown[Math.min(at, shown.length - 1)] : undefined
  const rest = active && text && active.label.toLowerCase().startsWith(text.toLowerCase()) ? active.label.slice(text.length) : ""
  const origin = useLineOrigin<HTMLInputElement>((el) => el, { onFocus, onPointerDown })

  const choose = (o: ComboboxOption) => {
    if (disabled || readOnly) return
    if (valueProp === undefined) setOwn(o.value)
    onValueChange?.(o.value)
    setText(o.label)
    setOpen(false)
    // What was pencil is now yours: the word inks in.
    const el = input.current
    if (el && !still()) {
      const css = getComputedStyle(el)
      el.animate([{ color: css.getPropertyValue("--ot-pencil").trim() }, { color: css.color }], { duration: ms(css.getPropertyValue("--ot-moderato"), 320), easing: css.getPropertyValue("--ot-exhale").trim() || "ease-out" })
    }
  }

  const key = (e: React.KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(e)
    if (e.defaultPrevented || readOnly) return
    const atEnd = e.currentTarget.selectionStart === text.length
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault()
      if (!open) return setOpen(true)
      const n = shown.length || 1
      setAt((i) => (Math.min(i, n - 1) + (e.key === "ArrowDown" ? 1 : n - 1)) % n)
    } else if (e.key === "Enter" && active) {
      e.preventDefault()
      choose(active)
    } else if ((e.key === "Tab" && !e.shiftKey) || (e.key === (getComputedStyle(e.currentTarget).direction === "rtl" ? "ArrowLeft" : "ArrowRight") && atEnd)) {
      if (!rest || !active) return
      e.preventDefault()
      choose(active)
    } else if (e.key === "Escape" && open) {
      e.preventDefault()
      setOpen(false)
      setText(chosen?.label ?? "")
    }
  }

  return (
    <div data-slot="combobox" data-variant="pencil" data-force={force} className={cn("ot-combo-pencil", className)}>
      <span className="ot-combo-line">
        <input
          {...props}
          ref={composedRef}
          type="text"
          dir={dir} // the line and its pencil copy both take the direction of what's typed, so they stay in register
          role="combobox"
          autoComplete={props.autoComplete ?? "off"}
          spellCheck={props.spellCheck ?? false}
          aria-autocomplete="list"
          aria-expanded={open}
          aria-controls={listId}
          aria-activedescendant={active ? `${listId}-${shown.indexOf(active)}` : undefined}
          aria-label={named ?? (label && !field.id ? label : undefined)}
          aria-invalid={props["aria-invalid"] ?? field["aria-invalid"]}
          aria-describedby={props["aria-describedby"] ?? field["aria-describedby"]}
          id={id ?? field.id}
          disabled={disabled}
          readOnly={readOnly}
          placeholder={placeholder}
          value={text}
          className="ot-input"
          onChange={(e) => {
            onChange?.(e)
            if (e.defaultPrevented) return
            setText(e.target.value)
            setOpen(true)
            setAt(0)
          }}
          onClick={(e) => {
            onClick?.(e)
            if (!e.defaultPrevented && !readOnly) setOpen(true)
          }}
          onKeyDown={key}
          onBlur={(e) => {
            onBlur?.(e)
            if (e.defaultPrevented) return
            setOpen(false)
            const exact = options.find((o) => o.label.toLowerCase() === q)
            if (exact && exact.value !== value) choose(exact)
            else setText(chosen?.label ?? "")
          }}
          {...origin}
        />
        <span className="ot-combo-ghost" dir={dir} aria-hidden="true">
          {text}
          <span>{rest}</span>
        </span>
      </span>
      <ul id={listId} role="listbox" aria-label={label ?? placeholder} hidden={!open || !shown.length} className="ot-combo-list">
        {shown.map((o, i) => (
          <li
            key={o.value}
            id={`${listId}-${i}`}
            role="option"
            aria-selected={o === active}
            data-chosen={o.value === value ? "" : undefined}
            onMouseDown={(e) => e.preventDefault()} // keep focus on the line, so the pick lands before the blur
            onPointerMove={() => setAt(i)}
            onClick={() => choose(o)}
          >
            <Marked text={o.label} query={q} />
            {o.hint ? <span className="ot-command-hint">{o.hint}</span> : null}
          </li>
        ))}
      </ul>
      {open && !shown.length ? (
        <p className="ot-combo-empty" role="status">
          {empty}
        </p>
      ) : null}
    </div>
  )
}

export { Combobox, type ComboboxOption, type ComboboxProps }

@layer components {
  /* ── ot-combo ── a field that suggests. The closed line is a baseline like the input's;
     what you chose is yours, in italic. The open list is a ot-pop hung from it, holding
     a cmdk Command, so the letters you typed are marked in each match and the rows arrive in turn. */
  .ot-field > .ot-combo { grid-column: 1 / -1; }
  .ot-combo {
    appearance: none; position: relative; display: block; width: 100%; margin: 0; border: 0; border-radius: 0; outline: 0;
    padding: 0.3em 1.4em 0.42em 0; text-align: start; cursor: pointer;
    background:
      linear-gradient(var(--ot-accent), var(--ot-accent)) no-repeat var(--o, 0%) 100% / 0% var(--ot-stroke),
      linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / 100% var(--ot-hairline);
    color: var(--ot-ink);
    font-family: var(--ot-expression); font-style: italic; font-weight: 400;
    font-size: calc(var(--ot-mp) * var(--ot-expression-scale)); line-height: 1.3;
    transition: background-size var(--ot-moderato) var(--ot-exhale);
  }
  .ot-combo[data-placeholder] { font-family: var(--ot-voice); font-style: normal; font-size: var(--ot-mp); color: var(--ot-pencil); }
  .ot-combo-value { display: block; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
  .ot-combo::after {
    content: "↓" / ""; position: absolute; inset-inline-end: 0; bottom: 0.5em;
    font-family: var(--ot-voice); font-style: normal; font-size: var(--ot-pp); line-height: 1; color: var(--ot-pencil);
    transition: translate var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  .ot-combo:is(:hover, [data-force~="hover"])::after { translate: 0 2px; color: var(--ot-ink); }
  .ot-combo[data-state="open"]::after { color: var(--ot-ink); }
  .ot-combo:is(:focus-visible, [data-state="open"], [data-force~="focus"]) { background-size: 100% var(--ot-stroke), 100% var(--ot-hairline); }
  .ot-combo[aria-invalid="true"] { background-image: linear-gradient(var(--ot-signal), var(--ot-signal)), linear-gradient(var(--ot-signal), var(--ot-signal)); }
  .ot-combo:disabled {
    color: var(--ot-pencil); cursor: not-allowed;
    background-image: none, repeating-linear-gradient(90deg, var(--ot-rule-strong) 0 2px, transparent 2px 6px);
  }
  .ot-combo:disabled::after { content: none; }

  /* ── multiple ── what you chose is written on the line as one sentence in your italic: the badge's series tags,
     "Didot, Futura and Univers", ours the commas and the "and". The baseline runs under the whole line; the rest of it,
     after the last word, is the trigger that opens the list again. Pressing a word strikes it and the sentence closes up
     round the gap. It wraps like prose and the line stays under its last row. */
  .ot-field > .ot-combo-many { grid-column: 1 / -1; }
  .ot-combo-many {
    display: flex; flex-wrap: wrap; align-items: baseline; row-gap: 0.12em; padding: 0.3em 0 0.42em;
    font-size: var(--ot-mp); line-height: 1.3;
    background:
      linear-gradient(var(--ot-accent), var(--ot-accent)) no-repeat 0 100% / 0% var(--ot-stroke),
      linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / 100% var(--ot-hairline);
    transition: background-size var(--ot-moderato) var(--ot-exhale);
  }
  .ot-combo-many > .ot-tag { line-height: 1.3; }
  .ot-combo-many > .ot-combo { flex: 1 0 1.8em; align-self: stretch; width: auto; padding-block: 0; background: none; }
  .ot-combo-many > .ot-combo:not([data-placeholder]) { padding-inline-start: 0.4em; }
  .ot-combo-many > .ot-combo::after { bottom: 0.2em; }
  .ot-combo-many:has(> .ot-combo:is(:focus-visible, [data-state="open"], [data-force~="focus"])) { background-size: 100% var(--ot-stroke), 100% var(--ot-hairline); }
  .ot-combo-many:has(> .ot-combo[aria-invalid="true"]) { background-image: linear-gradient(var(--ot-signal), var(--ot-signal)), linear-gradient(var(--ot-signal), var(--ot-signal)); }
  .ot-combo-many[data-disabled] { background-image: none, repeating-linear-gradient(90deg, var(--ot-rule-strong) 0 2px, transparent 2px 6px); }
  .ot-combo-many[data-disabled] > .ot-tag { color: var(--ot-pencil); }
  :is([dir="rtl"], [dir="rtl"] *).ot-combo-many { background-position: 100% 100%, 0 100%; }

  /* The panel: as wide as the line, the search inside it set a size down from the palette's. */
  .ot-pop.ot-combo-pop { width: max(var(--radix-popover-trigger-width), 16rem); max-width: calc(100vw - 2 * var(--ot-margin)); padding: var(--ot-space-4) 0 var(--ot-space-2); } /* as wide as its line, past the popover's own cap */
  .ot-combo-pop .ot-command { gap: var(--ot-space-3); }
  .ot-combo-pop .ot-command-input { width: calc(100% - 2 * var(--ot-space-5)); margin-inline: var(--ot-space-5); font-size: calc(var(--ot-mp) * var(--ot-expression-scale)); }
  .ot-combo-pop .ot-command-input::placeholder { font-size: var(--ot-mp); }
  .ot-combo-pop .ot-command-list { max-height: 17rem; overscroll-behavior: contain; }

  /* A row: a dot marks the one you point at (ink) and the one you chose (accent); the arrow the palette
     draws is put away. */
  .ot-pop.ot-combo-pop .ot-command-option {
    position: relative; padding: 0.32em var(--ot-space-5) 0.32em calc(var(--ot-space-5) + 0.7em); border-bottom: 0;
  }
  .ot-pop.ot-combo-pop .ot-command-option::after { content: none; }
  .ot-pop.ot-combo-pop .ot-command-option::before {
    content: ""; position: absolute; inset-inline-start: var(--ot-space-5); top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%;
    background: var(--ot-ink); scale: 0; transition: scale var(--ot-moderato) var(--ot-spiccato);
  }
  .ot-pop.ot-combo-pop .ot-command-option[aria-selected="true"] .ot-command-name { translate: 0 0; }
  .ot-pop.ot-combo-pop .ot-command-option[aria-selected="true"]::before { scale: 1; }
  .ot-pop.ot-combo-pop .ot-command-option[data-chosen] { color: var(--ot-ink); }
  .ot-pop.ot-combo-pop .ot-command-option[data-chosen]::before { background: var(--ot-accent); scale: 1; }
  .ot-combo-pop .ot-command-empty { padding-inline: var(--ot-space-5); color: var(--ot-pencil); }

  /* multiple: no accent in the list, since there are many choices and one accent. A chosen row is written in your italic,
     as it is on the line; the ink dot is only the one you point at. The leading is held so a row doesn't grow as it turns. */
  .ot-pop.ot-combo-pop[data-multiple] .ot-command-option[data-chosen]::before { background: var(--ot-ink); scale: 0; }
  .ot-pop.ot-combo-pop[data-multiple] .ot-command-option[data-chosen][aria-selected="true"]::before { scale: 1; }
  .ot-combo-pop[data-multiple] .ot-command-option[data-chosen] :is(.ot-command-name, .ot-combo-pre, .ot-combo-hit, .ot-combo-post) {
    font-family: var(--ot-expression); font-style: italic; font-size: calc(var(--ot-mp) * var(--ot-expression-scale)); line-height: calc(var(--ot-mp) * var(--ot-mp-lh));
  }
  .ot-combo-pop[data-multiple] .ot-command-option[data-chosen] .ot-command-hint { font-family: var(--ot-voice); font-style: normal; }

  /* ── concordance ── as a concordance sets a word in the middle of every line that holds it:
     each match is split round what you typed, and the typed letters stand in one column. The
     axis sits just after the longest start, so no row travels further than it must; typing
     moves it, and the rows glide to it (script, on the row). */
  .ot-combo-pop[data-variant="concordance"] [cmdk-list-sizer] { display: grid; grid-template-columns: auto auto minmax(0, 1fr); }
  .ot-combo-pop[data-variant="concordance"] [cmdk-list-sizer] > * { grid-column: 1 / -1; }
  .ot-pop.ot-combo-pop[data-variant="concordance"] .ot-command-option { grid-template-columns: subgrid; grid-auto-flow: row; column-gap: 0; font-size: var(--ot-mp); line-height: var(--ot-mp-lh); }
  .ot-combo-pre { text-align: end; white-space: pre; color: var(--ot-pencil); transition: color var(--ot-allegro); }
  .ot-combo-hit { white-space: pre; color: var(--ot-ink); }
  .ot-combo-hit > mark { padding: 0; margin: 0; }
  .ot-combo-post { min-width: 0; overflow: hidden; white-space: pre; text-overflow: ellipsis; }
  .ot-combo-post > .ot-command-hint { margin-inline-start: var(--ot-space-3); }
  .ot-command-option:is(:hover, [aria-selected="true"]) .ot-combo-pre { color: inherit; }

  /* ── pencil ── you type on the line itself. The best match's remaining letters are pencilled in
     after the caret, in our roman, over a copy of what you typed that can't be seen; taking them
     inks the word into your italic. The few matches sit under the line, in the page, not over it. */
  .ot-field > .ot-combo-pencil { grid-column: 1 / -1; }
  .ot-combo-pencil { display: grid; row-gap: var(--ot-space-2); }
  .ot-combo-line { position: relative; display: block; }
  .ot-combo-line > .ot-input { position: relative; background-color: transparent; }
  .ot-combo-ghost {
    position: absolute; inset: 0; overflow: hidden; padding: 0.3em 0 0.42em; white-space: pre; pointer-events: none; color: transparent;
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-mp) * var(--ot-expression-scale)); line-height: 1.3;
  }
  .ot-combo-ghost > span { font-family: var(--ot-voice); font-style: normal; font-size: var(--ot-mp); color: var(--ot-pencil); }
  .ot-combo-pencil[data-force~="focus"] { outline: 0; }
  .ot-combo-pencil[data-force~="focus"] .ot-input { background-size: 100% var(--ot-stroke), 100% var(--ot-hairline); }
  .ot-combo-pencil .ot-combo-list { display: grid; margin: 0; padding: 0; list-style: none; }
  .ot-combo-pencil .ot-combo-list[hidden] { display: none; }
  .ot-combo-pencil [role="option"] {
    position: relative; display: flex; align-items: baseline; gap: var(--ot-space-3); padding-block: 0.15em; padding-inline-start: 0.9em; cursor: pointer;
    font-size: var(--ot-p); line-height: var(--ot-p-lh); color: var(--ot-pencil); transition: color var(--ot-allegro);
    animation: ot-arrive var(--ot-moderato) var(--ot-exhale) backwards; animation-delay: calc(min(sibling-index(), 6) * var(--ot-arpeggio));
  }
  .ot-combo-pencil [role="option"]::before {
    content: ""; position: absolute; inset-inline-start: 0; top: calc(50% - 2.5px); width: 5px; height: 5px; border-radius: 50%;
    background: var(--ot-ink); scale: 0; transition: scale var(--ot-moderato) var(--ot-spiccato);
  }
  .ot-combo-pencil [role="option"][aria-selected="true"] { color: var(--ot-ink); }
  .ot-combo-pencil [role="option"][aria-selected="true"]::before { scale: 1; }
  .ot-combo-pencil [role="option"][data-chosen]::before { background: var(--ot-accent); scale: 1; }
  .ot-combo-pencil [role="option"] mark { padding: 0; margin: 0; }
  .ot-combo-pencil .ot-combo-empty { margin: 0; font-size: var(--ot-p); color: var(--ot-pencil); }

  @media (forced-colors: active) {
    .ot-combo-ghost { forced-color-adjust: none; }
    .ot-combo-ghost > span { color: GrayText; }
    .ot-combo-pencil [role="option"][aria-selected="true"] { color: Highlight; }
    .ot-combo-pencil [role="option"]::before { forced-color-adjust: none; background: CanvasText; }
  }
}
